// https://ffhacktics.com/wiki/SCUS_GameLoop

void GameLoop(void)

{
  int iVar1;
  bool _stream_movie;
  
  Stream_openmovie = 0;
  do {
    StartingInventory();
    _stream_movie = Stream_openmovie == 5;
    if (!_stream_movie) {
      FUN_80042690();
    }
    iVar1 = Get_OPEN_CDROM_to_RAM((uint)_stream_movie);
    if (iVar1 == 0) {
      BYTE_800473a0 = 1;
      Stream_openmovie = 0;
    }
    else {
      BYTE_800473a0 = 0;
    }
    do {
      if (BYTE_800473a0 == 0) {
        Stream_openmovie = Open_WORLD_WLDCORE(1);
      }
      if (Stream_openmovie == 5) break;
      Get_BATTLE_BIN();
      BATTLE_main();
      FUN_800440cc();
      BYTE_800473a0 = 0;
      if (DAT_800a778c == 2) {
        SCUS_game_reset_quit_sound();
        break;
      }
    } while (DAT_800a778c != 3);
    if (DAT_800a778c == 3) {
      FUN_800440cc();
      Unload_ScenarioSongs_and_SFX();
      BATTLE_set_script_variable(NewScenario,1);
      BATTLE_set_script_variable(CurrentEvent,0x12a);
      Get_OPEN_CDROM_to_RAM2();
      Get_BATTLE_BIN();
      Get_ZODIAC_CDROM_to_FrameBuffer();
      FUN_80079a98();
      SCUS_game_reset_quit_sound();
    }
  } while( true );
}



void main(void)

{
  SetGameRunning();
  Initialise_Game_Environment();
  Put_Stack_Pointer(&GlobalStackPointer);
  GameLoop();
  PadStop();
  StopCallback();
  return;
}



