// https://ffhacktics.com/wiki/Special_Status_Flag_Enabling
// 
// # Return Value
//   bool: false(0) if unit has no misc data, true(1) in every other situation

bool BATTLE_enable_special_status_flag(int special_status,int section,int unit_battle_id)

{
  ENTDDisplayUnitData *unit_misc_data;
  uint status_add_56;
  int uVar2;
  int iVar2;
  
  unit_misc_data = BATTLE_get_unit_misc_data_from_battle_id((ushort)unit_battle_id);
  if (unit_misc_data == (ENTDDisplayUnitData *)0x0) {
    return false;
  }
  if (section != 1) {
    if (1 < section) {
      return true;
    }
    if (section == 0) {
      switch(special_status) {
      case 1:
      case 10:
      case 0x10:
      case 0x20:
        return true;
      case 2:
      case 0x16:
        unit_misc_data->StatusesRem56 = unit_misc_data->StatusesRem56 | 2;
        status_add_56 = unit_misc_data->StatusesAdd56;
        uVar2 = -3;
        break;
      default:
        unit_misc_data->StatusesRem1234 =
             unit_misc_data->StatusesRem1234 | BATTLE_Status_Flags[special_status];
        unit_misc_data->StatusesAdd1234 =
             ~BATTLE_Status_Flags[special_status] & unit_misc_data->StatusesAdd1234;
        return true;
      case 6:
      case 0x12:
      case 0x14:
        unit_misc_data->StatusesRem56 =
             unit_misc_data->StatusesRem56 | BATTLE_Status_Flags[special_status];
        uVar2 = unit_misc_data->StatusesAdd56;
        status_add_56 = ~BATTLE_Status_Flags[special_status];
        break;
      case 0x17:
        unit_misc_data->StatusesRem56 = unit_misc_data->StatusesRem56 | 4;
        unit_misc_data->StatusesAdd56 = unit_misc_data->StatusesAdd56 & 0xfffffffb;
        BATTLE_ai_ability_setting_by_battle_id(unit_battle_id);
        return true;
      }
      unit_misc_data->StatusesAdd56 = status_add_56 & uVar2;
      return true;
    }
    return true;
  }
  switch(special_status) {
  case 1:
  case 10:
  case 0x20:
    goto out;
  case 2:
    unit_misc_data->StatusesAdd56 = unit_misc_data->StatusesAdd56 | 1;
    status_add_56 = unit_misc_data->StatusesRem56;
    iVar2 = -2;
    break;
  default:
    unit_misc_data->StatusesAdd1234 =
         unit_misc_data->StatusesAdd1234 | BATTLE_Status_Flags[special_status];
    unit_misc_data->StatusesRem1234 =
         ~BATTLE_Status_Flags[special_status] & unit_misc_data->StatusesRem1234;
    return true;
  case 6:
  case 0x12:
  case 0x14:
    unit_misc_data->StatusesAdd56 =
         unit_misc_data->StatusesAdd56 | BATTLE_Status_Flags[special_status];
    iVar2 = unit_misc_data->StatusesRem56;
    status_add_56 = ~BATTLE_Status_Flags[special_status];
    break;
  case 0x10:
    unit_misc_data->StatusesAdd56 = unit_misc_data->StatusesAdd56 | 8;
    status_add_56 = unit_misc_data->StatusesRem56;
    iVar2 = 0xfffffff7;
    break;
  case 0x16:
    unit_misc_data->StatusesAdd56 = unit_misc_data->StatusesAdd56 | 2;
    status_add_56 = unit_misc_data->StatusesRem56;
    iVar2 = 0xfffffffd;
    break;
  case 0x17:
    unit_misc_data->StatusesAdd56 = unit_misc_data->StatusesAdd56 | 4;
    unit_misc_data->StatusesRem56 = unit_misc_data->StatusesRem56 & 0xfffffffb;
    BATTLE_ai_ability_setting_by_battle_id(unit_battle_id);
    return true;
  }
  unit_misc_data->StatusesRem56 = status_add_56 & iVar2;
out:
  return true;
}



