// https://ffhacktics.com/wiki/Play_Sound_Effect_based_on_Movement_Flag

void BATTLE_play_sound_based_on_move_flag(ENTDDisplayUnitData *misc_unit_data,SFX_ID sound_fx_id)

{
  ENTDMoveMovementFlagsWord move_data;
  
  move_data._0_1_ = misc_unit_data->MoveX;
  move_data._1_1_ = misc_unit_data->MoveY;
  move_data._2_1_ = misc_unit_data->MoveZ;
  move_data._3_1_ = misc_unit_data->MoveMovementFlags;
  // Movement Flag 0x2 = unit walking?
  if ((move_data & Walking) == 0) {
    SCUS_MRTA_call_play_sound_find_channel(sound_fx_id);
  }
  return;
}



// https://ffhacktics.com/wiki/Play_Landing_SFX_based_on_tile

void BATTLE_play_landing_sfx_based_on_tile(ENTDDisplayUnitData *misc_data)

{
  uint moveflags;
  MapTileData *tile_data;
  SFX_ID sfx_id;
  
  moveflags._0_1_ = misc_data->MoveX;
  moveflags._1_1_ = misc_data->MoveY;
  moveflags._2_1_ = misc_data->MoveZ;
  moveflags._3_1_ = misc_data->MoveMovementFlags;
  if (((moveflags & 0x2000000) == 0) &&
     (tile_data = BATTLE_get_tile_data_ptr
                            ((uint)misc_data->MoveX,(uint)misc_data->MoveY,(uint)misc_data->MoveZ),
     tile_data != (MapTileData *)0x0)) {
    switch(tile_data->TileType & CrossSection) {
    case Grassland:
    case Thicket:
    case Rug:
      sfx_id = Land1;
      break;
    default:
      sfx_id = Land2;
      break;
    case Swamp:
    case Marsh:
    case PoisonMarsh:
    case Waterway:
    case River:
    case Lake:
    case Sea:
    case Waterfall:
      sfx_id = WaterLand1;
      break;
    case WoodenFloor:
    case Tree:
    case Box:
      sfx_id = LandWood;
    }
    SCUS_MRTA_call_play_sound_find_channel(sfx_id);
  }
  return;
}



// https://ffhacktics.com/wiki/Palette_adjustment_based_on_Tile_Type

void BATTLE_palette_adjustment_from_tile_type(ENTDDisplayUnitData *misc_unit_data)

{
  uint move_data;
  MapTileData *tile_data;
  
  move_data._0_1_ = misc_unit_data->MoveX;
  move_data._1_1_ = misc_unit_data->MoveY;
  move_data._2_1_ = misc_unit_data->MoveZ;
  move_data._3_1_ = misc_unit_data->MoveMovementFlags;
  if (((move_data & 0x2000000) == 0) &&
     (tile_data = BATTLE_get_tile_data_ptr
                            ((uint)misc_unit_data->MoveX,(uint)misc_unit_data->MoveY,
                             (uint)misc_unit_data->MoveZ), tile_data != (MapTileData *)0x0)) {
    switch(tile_data->TileType & CrossSection) {
    case SandArea:
    case Stalactite:
    case RockyCliff:
    case Gravel:
    case Wasteland:
    case LavaRocks:
    case Ice:
    case Road:
    case WoodenFloor:
    case StoneFloor:
    case Roof:
    case StoneWall:
    case Salt:
    case Book:
    case Tree:
    case Box:
    case Brick:
    case Chimney:
    case MudWall:
    case Bridge:
    case Stairs:
    case Deck:
    case Machine:
    case IronPlate:
    case Tombstone:
    case Coffin:
      BATTLE_fall_dust_cloud_secondary_effect(misc_unit_data);
      break;
    case Swamp:
    case Marsh:
    case PoisonMarsh:
    case Waterway:
    case River:
    case Lake:
    case Sea:
    case Waterfall:
      BATTLE_splash_secondary_effect(misc_unit_data);
    }
  }
  return;
}



