// https://ffhacktics.com/wiki/Store_Name_and_data_of_unit_selected_by_cursor

void BATTLE_store_name_and_unit_data_under_cursor(void)

{
  ENTDDisplayUnitData *unit_misc_data;
  int store_flag;
  uint unit_id2;
  
  unit_misc_data =
       BATTLE_get_misc_data_at_map_coords_2
                 (BATTLE_Cursor_X_Coord,BATTLE_Cursor_Y_Coord,BATTLE_Cursor_Z_Coord);
  store_flag = 2;
  if (unit_misc_data == (ENTDDisplayUnitData *)0x0) {
    store_flag = 1;
    unit_id2 = 0xff;
  }
  else {
    unit_id2 = (uint)(unit_misc_data->UnitBattleData->CurActionTargetData).UnitID2;
  }
  BATTLE_store_unit_names_and_event_block_data(store_flag,unit_id2,0xff);
  return;
}



// https://ffhacktics.com/wiki/Store_Name_and_Data_of_unit_selected_by_cursor_2

