// https://ffhacktics.com/wiki/Rotate_Camera_when_Unit_Tile_is_Not_Visible

void BATTLE_rotate_camera_when_unit_tile_obscured(ENTDDisplayUnitData *unit_misc_data)

{
  MapTileBannedCameraPosition ban_result;
  MapTileData *tile_data;
  uint current_rotation;
  MapTileBannedCameraPosition banned;
  int map_rot_value;
  
  tile_data = BATTLE_get_tile_data_ptr
                        ((uint)unit_misc_data->MapX,(uint)unit_misc_data->MapY,
                         (uint)unit_misc_data->MapZ);
  // SouthBottomLeft  0x200 >> 10 == 0
  // SouthTopLeft     0x600 >> 10 == 1
  // SouthTopRight    0xa00 >> 10 == 2
  // SouthBottomRight 0xe00 >> 10 == 3
  current_rotation = (int)(-(int)(short)BATTLE_Camera_Yaw_Angle & 0xfffU) >> 0xa;
  if ((short)BATTLE_Camera_Pitch_Angle < 0x178) {
    banned = tile_data->BannedCameraPosition & (NorthEastTop|SouthEastTop|SouthWestTop|NorthWestTop)
    ;
  }
  else {
    banned = tile_data->BannedCameraPosition >> 0x4;
  }
  if (current_rotation == 1) {
  // 1 == South to Top Left
    if ((banned & SouthWestTop) == NoBannedCamera) {
      return;
    }
    if ((banned & NorthWestTop) == NoBannedCamera) {
      map_rot_value = 0x400;
      goto rotate;
    }
    ban_result = banned & NorthEastTop;
    if ((banned & SouthEastTop) == NoBannedCamera) {
  // Rotate camera 90 degrees left
      map_rot_value = -0x400;
      goto rotate;
    }
  }
  else if (current_rotation < 2) {
  // 0 == South to Bottom Left
    if (current_rotation != 0) {
      return;
    }
    if ((banned & NorthWestTop) == NoBannedCamera) {
      return;
    }
    if ((banned & NorthEastTop) == NoBannedCamera) {
  // Rotate camera 90 degrees right
      map_rot_value = 0x400;
      goto rotate;
    }
    ban_result = banned & SouthEastTop;
    if ((banned & SouthWestTop) == NoBannedCamera) {
  // Rotate camera 90 degrees left
      map_rot_value = -0x400;
      goto rotate;
    }
  }
  else if (current_rotation == 2) {
  // 2 == South to Top Right
    if ((banned & SouthEastTop) == NoBannedCamera) {
      return;
    }
    if ((banned & SouthWestTop) == NoBannedCamera) {
  // Rotate camera 90 degrees right
      map_rot_value = 0x400;
      goto rotate;
    }
    ban_result = banned & NorthWestTop;
    if ((banned & NorthEastTop) == NoBannedCamera) {
  // Rotate camera 90 degrees left
      map_rot_value = -0x400;
      goto rotate;
    }
  }
  else {
  // 3 == South to Bottom Right
    if (current_rotation != 3) {
      return;
    }
    if ((banned & NorthEastTop) == NoBannedCamera) {
      return;
    }
    if ((banned & SouthEastTop) == NoBannedCamera) {
  // Rotate camera 90 degrees right
      map_rot_value = 0x400;
      goto rotate;
    }
    ban_result = banned & SouthWestTop;
    if ((banned & NorthWestTop) == NoBannedCamera) {
  // Rotate camera 90 degrees left
      map_rot_value = -0x400;
      goto rotate;
    }
  }
  // Rotate camera 180 degrees
  map_rot_value = 0x800;
  if (ban_result != NoBannedCamera) {
    return;
  }
rotate:
  BATTLE_map_rotation(map_rot_value);
  return;
}



