// https://ffhacktics.com/wiki/Decide_Facing_Direction
// 
// Param 2 is either:
// - result of BATTLE_free_cursor_input()
// - Facing Direction

void BATTLE_decide_facing_direction(ENTDDisplayUnitData *unit_misc_data,int facing_dir)

{
  if (facing_dir != 0x600) {
    if (facing_dir < 0x601) {
      if (facing_dir == 0x200) {
        return;
      }
      if (facing_dir < 0x201) {
        if (facing_dir != 0) {
          return;
        }
        if (unit_misc_data->CurrentFacing == FacingSouth) {
          return;
        }
        unit_misc_data->CurrentFacing = FacingSouth;
      }
      else {
        if (facing_dir != 0x400) {
          return;
        }
        if (unit_misc_data->CurrentFacing == FacingWest) {
          return;
        }
        unit_misc_data->CurrentFacing = FacingWest;
      }
    }
    else {
      if (facing_dir == 0xa00) {
        return;
      }
      if (facing_dir < 0xa01) {
        if (facing_dir != 0x800) {
          return;
        }
        if (unit_misc_data->CurrentFacing == FacingNorth) {
          return;
        }
        unit_misc_data->CurrentFacing = FacingNorth;
      }
      else {
        if (facing_dir != 0xc00) {
          return;
        }
        if (unit_misc_data->CurrentFacing == FacingEast) {
          return;
        }
        unit_misc_data->CurrentFacing = FacingEast;
      }
    }
    BATTLE_set_anim_from_status(unit_misc_data);
  }
  return;
}



