// https://ffhacktics.com/wiki/Undo_Mount

void BATTLE_undo_mount(ENTDDisplayUnitData *misc_data)

{
  ENTDDisplayUnitData *mount_misc_data;
  ENTDDisplayUnitData *rider_misc_data;
  uint status1234_1;
  uint status1234_2;
  
  if (misc_data->MountVal == CurrentlyRiding) {
    mount_misc_data = BATTLE_get_unit_misc_data_from_entd_id((ushort)misc_data->MountENTDID);
    mount_misc_data->MountVal = NotMounted;
    BATTLE_update_anim_display_by_entd_id((ushort)mount_misc_data->ENTDID);
  }
  BATTLE_move_to_previous_map_square(misc_data);
  if (misc_data->MountVal == BeingRidden) {
    rider_misc_data = BATTLE_get_unit_misc_data_from_entd_id((ushort)misc_data->MountENTDID);
    if (rider_misc_data != (ENTDDisplayUnitData *)0x0) {
      BATTLE_move_to_previous_map_square(rider_misc_data);
      BATTLE_update_anim_display_by_entd_id((ushort)rider_misc_data->ENTDID);
    }
  }
  else if (misc_data->MountVal == CurrentlyRiding) {
  // WARNING: impossible condition, can never be true
    status1234_1._0_1_ = misc_data->StatusFlag1;
    status1234_1._1_1_ = misc_data->StatusFlag2;
    status1234_1._2_1_ = misc_data->StatusFlag3;
    status1234_1._3_1_ = misc_data->StatusFlag4;
    status1234_1 = status1234_1 | Mounted;
    misc_data->StatusFlag1 = (char)status1234_1;
    misc_data->StatusFlag2 = (char)(status1234_1 >> 8);
    misc_data->StatusFlag3 = (char)(status1234_1 >> 0x10);
    misc_data->StatusFlag4 = (char)(status1234_1 >> 0x18);
    mount_misc_data = BATTLE_get_unit_misc_data_from_entd_id((ushort)misc_data->MountENTDID);
    if (mount_misc_data != (ENTDDisplayUnitData *)0x0) {
      mount_misc_data->MountVal = BeingRidden;
      mount_misc_data->MountENTDID = misc_data->ENTDID;
      BATTLE_update_anim_display_by_entd_id((ushort)mount_misc_data->ENTDID);
    }
  }
  else {
    status1234_2._0_1_ = misc_data->StatusFlag1;
    status1234_2._1_1_ = misc_data->StatusFlag2;
    status1234_2._2_1_ = misc_data->StatusFlag3;
    status1234_2._3_1_ = misc_data->StatusFlag4;
    status1234_2 = status1234_2 & 0xfffffffd;
    misc_data->StatusFlag1 = (char)status1234_2;
    misc_data->StatusFlag2 = (char)(status1234_2 >> 8);
    misc_data->StatusFlag3 = (char)(status1234_2 >> 0x10);
    misc_data->StatusFlag4 = (char)(status1234_2 >> 0x18);
  }
  BATTLE_update_anim_display_by_entd_id((ushort)misc_data->ENTDID);
  return;
}



