// https://ffhacktics.com/wiki/Main_TargetingRange_Game_State_Handler
// 
// Called from BATTLE_main in the switch-case for Game State.
// This is called in the "TargetingRange" case.

void BATTLE_main_TargetingRange_state_handler(void)

{
  ENTDDisplayUnitData *acting_misc_data;
  void **otag_list;
  MapTileData *cursor_tile;
  ENTDDisplayUnitData *target_misc_data;
  uint x_coord;
  uint y_coord;
  uint z_coord;
  ushort frame_data;
  
  acting_misc_data = BATTLE_get_acting_unit_misc_data();
  BATTLE_free_cursor_controller_input();
  otag_list = SCUS_get_OTAG_list();
  BATTLE_data_setting_from_menu_selections(otag_list,SCUS_Controller_Input_Copy_1);
  if ((acting_misc_data->ENTDFlags & PlayerControl) != None) {
  // unit is under player control
    BATTLE_move_cursor_based_on_input();
    BATTLE_button_input_map_rotation();
    BATTLE_call_map_zoom();
    BATTLE_call_map_tilt();
    if ((SCUS_Controller_Input & ButtonCross) != NoButtons) {
      BATTLE_tile_bg_color_partial(0,2);
      BATTLE_active_unit_idle_action_menu();
      return;
    }
    if ((SCUS_Controller_Input & ButtonCircle) == NoButtons) {
      return;
    }
    cursor_tile = BATTLE_get_tile_data_ptr
                            (BATTLE_Cursor_X_Coord,BATTLE_Cursor_Y_Coord,BATTLE_Cursor_Z_Coord);
    if ((cursor_tile->Overlay & Overlay0x40) != New_Name) {
      BATTLE_select_target_tile();
      return;
    }
    BATTLE_target_out_of_range();
    return;
  }
  if (acting_misc_data->TileOrTarget == 5) {
    BATTLE_free_cursor_selection(acting_misc_data,(ENTDDisplayUnitData *)0x0);
    frame_data = acting_misc_data->FrameData;
    acting_misc_data->FrameData = frame_data + 1;
    if (frame_data < 0x1f) {
      return;
    }
    x_coord = (uint)acting_misc_data->TargetX;
    y_coord = (uint)acting_misc_data->TargetY;
    z_coord = (uint)acting_misc_data->TargetZ;
  }
  else {
    if (acting_misc_data->TileOrTarget != 6) {
      return;
    }
    target_misc_data = BATTLE_get_unit_misc_data_from_battle_id((ushort)acting_misc_data->TargetID2)
    ;
    if (target_misc_data == (ENTDDisplayUnitData *)0x0) {
      SetActionMenuScript();
      return;
    }
    BATTLE_free_cursor_selection(acting_misc_data,target_misc_data);
    frame_data = acting_misc_data->FrameData;
    acting_misc_data->FrameData = frame_data + 1;
    if (frame_data < 0x1f) {
      return;
    }
    x_coord = (uint)target_misc_data->MapX;
    y_coord = (uint)target_misc_data->MapY;
    z_coord = (uint)target_misc_data->MapZ;
  }
  BATTLE_get_tile_data_ptr(x_coord,y_coord,z_coord);
  BATTLE_select_target_tile();
  return;
}



