// 
// Ramps input up to a ceiling of 127 (0x7f) quicker than plain input = output

int BATTLE_ramp_up_to_0x7f(int input)

{
  int result;
  
  if (input == 0) {
    result = 0;
  }
  else if (input < 0x60) {
    result = (input * 0x7f) / 0x60;
  }
  else {
    result = 0x7f;
  }
  return result;
}



