int BATTLE_player_item_quantity_decrement
              (BattleUnitData *unit_battle_stats,uint used_item_id,int always_one)

{
  if (((unit_battle_stats->CurActionUnitData).ModifiedENTDTeam & LightBlueTeam) == None) {
  // If unit is enemy unit, jump to return 0
    if (SCUS_Available_Item_Quantities[used_item_id & 0xff] == 0) {
      return -1;
    }
    if (always_one == 0) {
      return 0;
    }
    if (ActionState != 0) {
      return 0;
    }
    SCUS_Available_Item_Quantities[used_item_id & 0xff] =
         SCUS_Available_Item_Quantities[used_item_id & 0xff] - 1;
  }
  return 0;
}



// https://ffhacktics.com/wiki/Prep_Current_Action_Data
// 
// Returns:
//  r2 = 0x00 If Ability is used (and updated)
//  -- All cases bellow abort action -- (Attacker 0x16e to 0x181 are cleared)
//  r2 = 0x08 if Unit is in deep water
//  r2 = 0x07 if unit can't act
//  r2 = 0x06 If Hamedo is triggered (no action)
//  r2 = 0x05 if unit is a frog attempting to do non frog things
//  r2 = 0x03 if unit does not have enough MP (And action menu = default)
//  r2 = 0x02 if unit is silenced and [Action menu = default or monster] and [Ability is silencable]

int BATTLE_prep_current_action_data(int unit_battle_id)

{
  int ability_usage_result;
  int counter;
  BattleUnitData *unit_battle_stats;
  BattleUnitData *battle_data_iter;
  
  BATTLE_Acting_Unit_Battle_ID = -1;
  BATTLE_Type_Of_Action = 0;
  if (unit_battle_id < 0x15) {
    battle_data_iter = UnitBattleData;
    unit_battle_stats = UnitBattleData + unit_battle_id;
    if (UnitBattleData[unit_battle_id].AllActionUnitData.UnitID != 0xff) {
      if (CurrentAbilityData.Hamedo != 0) {
        BATTLE_store_some_acting_unit_data(unit_battle_stats);
        return 6;
      }
      ability_usage_result = BATTLE_ability_usage_and_mp_reduce(unit_battle_stats);
      counter = 0;
      if (ability_usage_result != 0) {
        BATTLE_store_some_acting_unit_data(unit_battle_stats);
        return ability_usage_result;
      }
      BATTLE_Acting_Unit_Used_Ability_ID =
           UnitBattleData[unit_battle_id].CurActionTargetData.AttackToUse;
      BATTLE_Acting_Unit_Battle_ID = unit_battle_id;
      do {
        (battle_data_iter->CurActionUnitData).ReactionID = None;
        (battle_data_iter->CurActionTargetData).TurnFlags = None;
        counter = counter + 1;
        battle_data_iter = battle_data_iter + 1;
      } while (counter < 0x15);
      BATTLE_ability_hit_processing(unit_battle_stats);
      BATTLE_set_attacker_ability_data(unit_battle_stats);
      return 0;
    }
  }
  BATTLE_Acting_Unit_Battle_ID = -1;
  BATTLE_Type_Of_Action = 0;
  return -1;
}



