void ETC_Show_Graphic_Async(void)

{
  ETC_GraphicID graphic;
  
  graphic = Thread_getParam1();
  ETC_Open_Display_Graphic_to_FrameBuffer(graphic);
  if (ETC_graphicData[graphic].textureMode == 0) {
    ETC_Draw_Display_ChapterTitle(graphic);
  }
  else if (ETC_graphicData[graphic].textureMode == 1) {
    ETC_Draw_Display_GameOver(graphic);
  }
  BATTLE_stop_current_thread();
  return;
}



